WITH scope AS (SELECT DISTINCT unnest($1::text[]) AS principal), scope_agents AS (SELECT a.agent_id,a.principal FROM coordination_agents a WHERE a.principal=ANY($1::text[])), visible_mail AS MATERIALIZED (SELECT e.message_id FROM scope_agents a CROSS JOIN LATERAL (SELECT message_id FROM coordination_events WHERE event='send' AND agent_id>=a.agent_id AND agent_id<=a.agent_id AND principal>=a.principal AND principal<=a.principal ORDER BY agent_id DESC,principal DESC,seq DESC LIMIT $2) e UNION SELECT e.message_id FROM scope_agents a CROSS JOIN LATERAL (SELECT message_id FROM coordination_events WHERE event='send' AND recipient_agent_id>=a.agent_id AND recipient_agent_id<=a.agent_id ORDER BY recipient_agent_id DESC,seq DESC LIMIT $2) e), candidates AS ((SELECT e.* FROM scope s CROSS JOIN LATERAL (SELECT * FROM coordination_events WHERE principal>=s.principal AND principal<=s.principal AND event IN ('send','read','ack','attempt','served','woke','lease_expire') ORDER BY principal DESC,seq DESC LIMIT $2) e ORDER BY e.seq DESC LIMIT $2) UNION (SELECT e.* FROM visible_mail v CROSS JOIN LATERAL (SELECT * FROM coordination_events WHERE message_id>=v.message_id AND message_id<=v.message_id AND event IN ('send','read','ack','attempt','served','woke','lease_expire') ORDER BY message_id,event,created_at OFFSET 0) e ORDER BY e.seq DESC LIMIT $2) UNION (SELECT e.* FROM coordination_events e WHERE e.event='expire' AND EXISTS (SELECT 1 FROM jsonb_array_elements_text(e.payload::jsonb->'message_ids') AS ids(id) JOIN visible_mail v ON v.message_id=ids.id) ORDER BY e.seq DESC LIMIT $2)), timeline AS (SELECT e.seq,e.event,e.created_at,e.agent_id,e.recipient_agent_id,e.message_id,e.project,e.task, CASE e.event WHEN 'send' THEN e.payload::jsonb->>'wake' WHEN 'read' THEN e.payload::jsonb->>'path' END AS detail, CASE WHEN e.event='expire' THEN (SELECT count(*) FROM jsonb_array_elements_text(e.payload::jsonb->'message_ids') AS ids(id) JOIN visible_mail v ON v.message_id=ids.id) ELSE 0 END AS expired_count FROM candidates e) SELECT * FROM timeline ORDER BY seq DESC LIMIT $2
